// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// A function: every x has exactly one y.
// Not a function: at least one x has multiple different y values.

$isFunction = rand(0, 1); // 1 for yes, 0 for no

if ($isFunction == 1) {
    // Generate a set of 4 distinct x-values to ensure it is a function
    $x_vals = array();
    while (count($x_vals) < 4) {
        $v = rand(-5, 10);
        if (!in_array($v, $x_vals)) {
            $x_vals[] = $v;
        }
    }

    $pairs = array();
    for ($i = 0; $i < 4; $i++) {
        $pairs[] = "(" . $x_vals[$i] . ", " . rand(-5, 10) . ")";
    }
    $answer = 0; // Index of "Yes"
} else {
    // Generate a set where one x is repeated with different y values
    $x_repeat = rand(-5, 10);
    $y1 = rand(-5, 10);
    $y2 = rand(-5, 10);
    while ($y1 == $y2) {
        $y2 = rand(-5, 10);
    }

    $pairs = array();
    $pairs[0] = "(" . $x_repeat . ", " . $y1 . ")";
    $pairs[1] = "(" . $x_repeat . ", " . $y2 . ")";

    // Add two more distinct pairs to fill the set
    $x_vals = array($x_repeat);
    while (count($x_vals) < 3) {
        $v = rand(-5, 10);
        if (!in_array($v, $x_vals)) {
            $x_vals[] = $v;
        }
    }

    $pairs[2] = "(" . $x_vals[1] . ", " . rand(-5, 10) . ")";
    $pairs[3] = "(" . $x_vals[2] . ", " . rand(-5, 10) . ")";

    // Manual shuffle to avoid forbidden shuffle()
    for ($i = 0; $i < 4; $i++) {
        $target = rand(0, 3);
        $temp = $pairs[$i];
        $pairs[$i] = $pairs[$target];
        $pairs[$target] = $temp;
    }
    $answer = 1; // Index of "No"
}

// Manual string build to avoid forbidden implode()
$relation_text = "";
for ($i = 0; $i < 4; $i++) {
    $relation_text .= $pairs[$i];
    if ($i < 3) {
        $relation_text .= ", ";
    }
}

$questions = array(
    "Yes, it is a function",
    "No, it is not a function"
);

// === QUESTION TEXT ===
Determine if the following relationship is a function:

`{` $relation_text `}`

$answerbox

// === ANSWER ===
$solutionguide = 'A relationship is a function if every input (x-value) is paired with exactly one output (y-value). ' . 
($isFunction == 1 ? 'In this set, every x-value is unique, so it is a function.' : 'In this set, the x-value ' . $x_repeat . ' is paired with two different y-values, so it is not a function.');

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Randomize probabilities for two events A and B
// P(A) and P(B) should be reasonably large so that P(A or B) doesn't exceed 1 too easily
// P(A and B) must be less than or equal to the minimum of P(A) and P(B)
$pA = rand(0.3, 0.6) / 0.1; // This is a placeholder logic; using proper rand()
$pA = round(rand(30, 60) / 100, 2);
$pB = round(rand(30, 60) / 100, 2);

// Ensure P(A and B) is valid: 0 <= P(A and B) <= min(P(A), P(B))
$maxOverlap = min($pA, $pB);
$pAnd = round(rand(10, $maxOverlap * 100) / 100, 2);

// Calculate the union: P(A or B) = P(A) + P(B) - P(A and B)
$pOr = $pA + $pB - $pAnd;

// Check if P(A or B) > 1. If so, regenerate. 
// In a real IMathAS environment, we use a while loop or tighter constraints.
// To keep it simple and safe for all seeds:
if ($pOr > 1) {
    $pA = 0.4;
    $pB = 0.4;
    $pAnd = 0.2;
    $pOr = 0.6;
}

$answer[0] = $pOr;
$answer[1] = 1; // Index for the correct choice in part b

$anstypes = "numfunc,choices";
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";

// Options for part (b)
$questions[1][0] = "It undercounts the outcomes that are in both A and B.";
$questions[1][1] = "It counts the outcomes in the overlap twice.";
$questions[1][2] = "It ignores the outcomes that are only in A.";
$questions[1][3] = "It only works if the events are independent.";

// Formatting for display
$pA_disp = sprintf("%.2f", $pA);
$pB_disp = sprintf("%.2f", $pB);
$pAnd_disp = sprintf("%.2f", $pAnd);

// Solution Guide
$solutionguide = "Step 1 — Identify the given probabilities: `P(A) = $pA_disp`, `P(B) = $pB_disp`, and `P(A and B) = $pAnd_disp`.
Step 2 — Use the General Addition Rule: `P(A or B) = P(A) + P(B) - P(A and B)`.
Step 3 — Substitute the values: `$pA_disp + $pB_disp - $pAnd_disp = " . sprintf("%.2f", $pOr) . "`.
Step 4 — For part (b), recognize that adding `P(A)` and `P(B)` includes the overlap `P(A and B)` twice (once in A and once in B), so we must subtract it once to get the correct total.";

// === QUESTION TEXT ===
<p>Suppose two events, `A` and `B`, have the following probabilities:</p>
<ul>
  <li>`P(A) = $pA_disp`</li>
  <li>`P(B) = $pB_disp`</li>
  <li>`P(A and B) = $pAnd_disp`</li>
</ul>

<p>(a) Find the probability that event `A` or event `B` occurs: <br>
`P(A or B) =` $answerbox[0]</p>

<p>(b) If you simply added `P(A) + P(B)` without subtracting the overlap, why would the result be incorrect?</p>
$answerbox[1]

// === NAME - DESCRIPTION:  ===
