// We need a total N that is a "nice" number for percentages (reciprocal terminates)
$nTotal = 50;

// Categories: 4 categories.
$cats = array("Red", "Blue", "Green", "Yellow");

// Deal out counts to sum to $nTotal.
$counts = array();
$remaining = $nTotal;
for ($i = 0; $i < 3; $i++) {
  $val = rand(5, 15);
  $counts[$i] = $val;
  $remaining -= $val;
}
$counts[3] = $remaining;

// Compute percentages
$percents = array();
for ($i = 0; $i < 4; $i++) {
  $percents[$i] = ($counts[$i] / $nTotal) * 100;
}

// Part (a): Total sample size
$answer[0] = $nTotal;

// Part (b): Percentage for a specific category (randomly chosen)
$targetIdx = rand(0, 3);
$targetCat = $cats[$targetIdx];
$answer[1] = $percents[$targetIdx];

// Part (c): Why the shape is the same
$questions[2] = array(
  "The percentages are calculated by multiplying the counts by a constant factor, which scales all bars equally.",
  "The percentages are calculated by adding a constant value to each count, which shifts the bars up.",
  "The percentages are calculated by squaring the counts, which emphasizes the larger categories.",
  "The percentages are calculated by taking the square root of the counts, which compresses the larger categories."
);
$answer[2] = 0;

