$yMaxP = ceil(max($percents) / 10) * 10;

// Graph 1: Counts
$graphC = '<svg width="300" height="200" style="border:1px solid #ccc; background:#fff;">';
$graphC .= '<text x="150" y="20" text-anchor="middle" font-weight="bold">Counts</text>';
$graphC .= '<line x1="40" y1="160" x2="40" y2="40" stroke="black" />';
$graphC .= '<line x1="40" y1="160" x2="280" y2="160" stroke="black" />';
for ($t = 0; $t <= $yMaxC; $t += 5) {
  $yPos = 160 - ($t * (120 / $yMaxC));
  $graphC .= '<line x1="35" y1="' . $yPos . '" x2="40" y2="' . $yPos . '" stroke="black" />';
  $graphC .= '<text x="30" y="' . ($yPos + 4) . '" text-anchor="end" font-size="12">' . $t . '</text>';
}
$barW = 30;
