for ($i = 0; $i < 4; $i++) {
  $h = $counts[$i] * (120 / $yMaxC);
  $x = 60 + $i * ($barW + $gap);
  $y = 160 - $h;
  $graphC .= '<rect x="' . $x . '" y="' . $y . '" width="' . $barW . '" height="' . $h . '" fill="steelblue" stroke="black" />';
  $graphC .= '<text x="' . ($x + $barW/2) . '" y="175" text-anchor="middle" font-size="12">' . $cats[$i] . '</text>';
}
$graphC .= '</svg>';

// Graph 2: Percentages
$graphP = '<svg width="300" height="200" style="border:1px solid #ccc; background:#fff;">';
$graphP .= '<text x="150" y="20" text-anchor="middle" font-weight="bold">Percentages</text>';
$graphP .= '<line x1="40" y1="160" x2="40" y2="40" stroke="black" />';
$graphP .= '<line x1="40" y1="160" x2="280" y2="160" stroke="black" />';
for ($t = 0; $t <= $yMaxP; $t += 10) {
  $yPos = 160 - ($t * (120 / $yMaxP));
  $graphP .= '<line x1="35" y1="' . $yPos . '" x2="40" y2="' . $yPos . '" stroke="black" />';
  $graphP .= '<text x="30" y="' . ($yPos + 4) . '" text-anchor="end" font-size="12">' . $t . '%</text>';
}
for ($i = 0; $i < 4; $i++) {
  $h = $percents[$i] * (120 / $yMaxP);
  $x = 60 + $i * ($barW + $gap);
  $y = 160 - $h;
  $graphP .= '<rect x="' . $x . '" y="' . $y . '" width="' . $barW . '" height="' . $h . '" fill="steelblue" stroke="black" />';
  $graphP .= '<text x="' . ($x + $barW/2) . '" y="175" text-anchor="middle" font-size="12">' . $cats[$i] . '</text>';
}
$graphP .= '</svg>';

$sumStr = $counts[0] . ' + ' . $counts[1] . ' + ' . $counts[2] . ' + ' . $counts[3];
$solutionguide = 'Step 1: To find the total sample size, add the heights of all bars in the Counts graph. ' . $sumStr . ' = ' . $nTotal . '. <br>' .
  'Step 2: To find the percentage for ' . $targetCat . ', divide its count (' . $counts[$targetIdx] . ') by the total (' . $nTotal . ') and multiply by 100: ' . 
  '(' . $counts[$targetIdx] . ' / ' . $nTotal . ') * 100 = ' . $percents[$targetIdx] . '%. <br>' .
  'Step 3: The shape of the graph remains the same because every count is multiplied by the same constant (100/N) to get the percentage, which scales the y-axis linearly.';

