// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// We need a 2x2 table. To ensure expected counts are clean,
// we pick a total N that is a multiple of the row and column totals.
$nTotal = 200;
$row1Total = rand(60, 140); 
$row1Total = round($row1Total / 10) * 10;
$row2Total = $nTotal - $row1Total;

$col1Total = rand(60, 140);
$col1Total = round($col1Total / 10) * 10;
$col2Total = $nTotal - $col1Total;

// Expected count = (Row Total * Col Total) / Grand Total
$exp11 = ($row1Total * $col1Total) / $nTotal;
$exp12 = ($row1Total * $col2Total) / $nTotal;
$exp21 = ($row2Total * $col1Total) / $nTotal;
$exp22 = ($row2Total * $col2Total) / $nTotal;

// We define the cells. To avoid shuffle(), we use a random offset.
$cellLabels = array(
  "Row 1, Column 1",
  "Row 1, Column 2",
  "Row 2, Column 1",
  "Row 2, Column 2"
);
$cellValues = array(
  $exp11,
  $exp12,
  $exp21,
  $exp22
);

// Instead of shuffle, we pick a random starting offset and take 3 consecutive cells
$offset = rand(0, 3);
$idx0 = $offset;
$idx1 = ($offset + 1) % 4;
$idx2 = ($offset + 2) % 4;

$answer[0] = $cellValues[$idx0];
$answer[1] = $cellValues[$idx1];
$answer[2] = $cellValues[$idx2];

$qText[0] = $cellLabels[$idx0];
$qText[1] = $cellLabels[$idx1];
$qText[2] = $cellLabels[$idx2];

$anstypes = "number,number,number";
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";
$strflags[2] = "trim_whitespace";

// Context for the table
