$labelRow = $ctx[3];
$labelRow2 = $ctx[4];
$labelCol = $ctx[1];
$labelCol2 = $ctx[2];

// Precompute row/col totals for the solution guide
if ($idx0 < 2) { $r0 = $row1Total; } else { $r0 = $row2Total; }
if ($idx0 % 2 == 0) { $c0 = $col1Total; } else { $c0 = $col2Total; }

