if ($idx1 % 2 == 0) { $c1 = $col1Total; } else { $c1 = $col2Total; }

if ($idx2 < 2) { $r2 = $row1Total; } else { $r2 = $row2Total; }
if ($idx2 % 2 == 0) { $c2 = $col1Total; } else { $c2 = $col2Total; }

$solutionguide = 'The expected count for a cell in a contingency table is calculated using the formula: Expected Count = (Row Total * Column Total) / Grand Total. ' .
  'For ' . $qText[0] . ': (' . $r0 . ' * ' . $c0 . ') / ' . $nTotal . ' = ' . $answer[0] . '. ' .
  'For ' . $qText[1] . ': (' . $r1 . ' * ' . $c1 . ') / ' . $nTotal . ' = ' . $answer[1] . '. ' .
  'For ' . $qText[2] . ': (' . $r2 . ' * ' . $c2 . ') / ' . $nTotal . ' = ' . $answer[2] . '.';

