// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$scenarios = [
  [
    "text" => "A researcher wants to study the effect of a new vitamin supplement on memory. She recruits 100 volunteers and asks them to keep a diary of their daily supplement intake and their scores on a weekly memory test for three months.",
    "type" => "observational",
    "bias" => "self-reporting bias",
    "confounding" => "diet or sleep habits",
