  ]
];

// Pick a random scenario
$idx = rand(0, 3);
$s = $scenarios[$idx];

$scenarioText = $s["text"];

// Part 0: Classification (Choices)
$questions[0] = [
  "Observational Study",
  "Experimental Study"
];
$answer[0] = ($s["type"] == "observational") ? 0 : 1;

// Part 1: Bias/Confounding (String)
// We provide a few acceptable phrasings based on the scenario
if ($s["type"] == "observational") {
  $answer[1] = $s["bias"] . " or " . $s["confounding"];
} else {
  $answer[1] = $s["bias"];
}

// Part 2: Justified Conclusion (String)
$answer[2] = $s["justified"];

// Part 3: Not Justified Conclusion (String)
$answer[3] = $s["not_justified"];

