$strflags[1] = "ignore_case,trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";
$strflags[3] = "ignore_case,trim_whitespace";

// Build solution guide
$guide = "Step 1: Determine if the researcher manipulated a variable. ";
if ($s["type"] == "observational") {
  $guide .= "Since the researcher only observed existing behaviors without assigning treatments, this is an observational study. ";
  $guide .= "In such studies, confounding variables (like " . $s["confounding"] . ") can influence the result. ";
  $guide .= "Therefore, we can conclude there is an association, but we cannot claim causation.";
} else {
  $guide .= "Since the researcher randomly assigned participants to different treatment groups, this is an experimental study. ";
