# Randomly decide if c is above or below the mean to vary the probability
$direction = rand(0, 1) ? 1 : -1;
$c = $expectedSum + ($direction * $offset * rand(1, 3));

# Calculations for the sampling distribution of the sum
# Mean of the sum: mu_sum = n * mu
$muSum = $n * $mu;
# Standard deviation of the sum: sigma_sum = sqrt(n) * sigma
$sigmaSum = sqrt($n) * $sigma;

# Z-score for the sum: z = (c - mu_sum) / sigma_sum
$zScore = ($c - $muSum) / $sigmaSum;

# Probability P(Sigma x > c) = P(Z > zScore)
# IMathAS does not provide a built-in normal CDF function in the control block.
# We use the standard approximation for the normal CDF (error < 0.0001)
