$prob_left = 1.0 - $d * $t * (0.3193815 + $t * (-0.3565638 + $t * (1.781478 + $t * (-1.821256 + $t * 1.330274))));
if ($x < 0) {
    $prob_left = 1.0 - $prob_left;
}
$prob = 1 - $prob_left;

# Answers
