// === NAME - DESCRIPTION: Critical z and which area to use: turn a right-tail area into the left area for invNorm, find the critical z, then find the z-scores that bound the middle percent of the standard normal curve ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$anstypes = "number,number,number,number,number,number";

$idx = diffrands(0,6,2);
$idxTail = $idx[0];
$idxMid = $idx[1];

$tails = array(0.20,0.15,0.10,0.05,0.025,0.01,0.005);
$pcts = array(60,70,80,90,95,98,99);
$zs = array(0.8416,1.0364,1.2816,1.6449,1.9600,2.3263,2.5758);

$rtArea = $tails[$idxTail];
$rtLeft = round(1 - $rtArea, 4);
$rtZ = $zs[$idxTail];

$midPct = $pcts[$idxMid];
$midOutside = 100 - $midPct;
$midHalf = $midOutside / 2;
$midTail = round($midOutside / 200, 4);
$midLeft = round(1 - $midTail, 4);
$upperZ = $zs[$idxMid];
$lowerZ = -1 * $upperZ;

$answer = array($rtLeft, $rtZ, $midTail, $midLeft, $lowerZ, $upperZ);
$abstolerance = array(0.0005, 0.006, 0.0005, 0.0005, 0.006, 0.006);

// === QUESTION TEXT ===
<p>The invNorm command works with the area to the <strong>left</strong> of a z-score. It never accepts a right-tail area directly, so you have to decide which left area to give it. Give all areas as decimals and round each z-score to at least 2 decimal places.</p>

<p><strong>(a)</strong> The area in the right tail of the standard normal curve is $rtArea. What left area do you give invNorm?</p>
<p>Left area = $answerbox[0]</p>

<p><strong>(b)</strong> Find the critical value `z` that has a right-tail area of $rtArea.</p>
<p>Critical `z` = $answerbox[1]</p>

<p><strong>(c)</strong> Now look at the middle $midPct percent of the standard normal curve. The area that is left over is split equally between the two tails.</p>
<p>Area in each tail = $answerbox[2]</p>
<p>Left area to give invNorm for the upper boundary = $answerbox[3]</p>

<p><strong>(d)</strong> Find the two z-scores that bound the middle $midPct percent of the standard normal curve.</p>
<p>Lower `z` = $answerbox[4]</p>
<p>Upper `z` = $answerbox[5]</p>

// === ANSWER ===
$solutionguide = '<p><strong>Part (a)</strong></p>';
$solutionguide = $solutionguide . '<p>Step 1: invNorm uses the area to the left of z. The area in the right tail is ' . $rtArea . ', so the left area is everything else.</p>';
$solutionguide = $solutionguide . '<p>Step 2: Subtract the tail from the total area of 1: `1 - ' . $rtArea . ' = ' . $rtLeft . '`.</p>';
$solutionguide = $solutionguide . '<p>Answer: ' . $rtLeft . '. Entering the tail area ' . $rtArea . ' itself would give a z-score on the wrong side of the mean.</p>';

$solutionguide = $solutionguide . '<p><strong>Part (b)</strong></p>';
$solutionguide = $solutionguide . '<p>Step 1: Use the left area from part (a): ' . $rtLeft . '.</p>';
$solutionguide = $solutionguide . '<p>Step 2: Run invNorm with area ' . $rtLeft . ', mean 0, standard deviation 1.</p>';
$solutionguide = $solutionguide . '<p>Answer: `z = ' . $rtZ . '`, which is positive because more than half of the area lies to its left.</p>';

$solutionguide = $solutionguide . '<p><strong>Part (c)</strong></p>';
$solutionguide = $solutionguide . '<p>Step 1: The middle ' . $midPct . ' percent leaves `100 - ' . $midPct . ' = ' . $midOutside . '` percent for the two tails together.</p>';
$solutionguide = $solutionguide . '<p>Step 2: Split that equally: ' . $midOutside . ' divided by 2 is ' . $midHalf . ' percent in each tail, which is ' . $midTail . ' as a decimal.</p>';
$solutionguide = $solutionguide . '<p>Step 3: The area to the left of the upper boundary is the middle area plus the lower tail, or equivalently `1 - ' . $midTail . ' = ' . $midLeft . '`.</p>';
$solutionguide = $solutionguide . '<p>Answer: each tail is ' . $midTail . ' and the left area for the upper boundary is ' . $midLeft . '.</p>';

$solutionguide = $solutionguide . '<p><strong>Part (d)</strong></p>';
$solutionguide = $solutionguide . '<p>Step 1: Run invNorm with area ' . $midLeft . ', mean 0, standard deviation 1 to get the upper boundary.</p>';
$solutionguide = $solutionguide . '<p>Step 2: The normal curve is symmetric about 0, so the lower boundary is the opposite of the upper one. You can check it by running invNorm with area ' . $midTail . '.</p>';
$solutionguide = $solutionguide . '<p>Answer: lower `z = ' . $lowerZ . '` and upper `z = ' . $upperZ . '`.</p>';

