$matA = "[[$a11,$a12,$a13],[$a21,$a22,$a23],[$a31,$a32,$a33]]";
$matB = "[[$b1],[$b2],[$b3]]";
$matC = "[[$c11,$c12,$c13],[$c21,$c22,$c23],[$c31,$c32,$c33]]";
