// === NAME - DESCRIPTION: Rocket Height Model - Evaluate, Domain, Average Rate of Change - Evaluate a quadratic projectile model, give its contextual domain in interval notation, and compute an average rate of change. ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$b = randfrom(array(4,5,6,7,8));
$v0 = 16*$b;

// evaluation point, strictly inside the flight
$c = rand(1, $b - 1);
$c2 = $c*$c;
$term1c = -16*$c2;
$term2c = $v0*$c;
$hc = $term1c + $term2c;

// interval for the average rate of change, kept away from the symmetric case
$p = rand(0, $b - 1);
$q = rand($p + 1, $b);
if ($p + $q == $b) {
  if ($q < $b) { $q = $q + 1; } else { $p = $p + 1; }
}
$p2 = $p*$p;
$q2 = $q*$q;
$term1p = -16*$p2;
$term2p = $v0*$p;
$hp = $term1p + $term2p;
$term1q = -16*$q2;
$term2q = $v0*$q;
$hq = $term1q + $term2q;
$dh = $hq - $hp;
$dt = $q - $p;
$aroc = $dh/$dt;

$anstypes = array("number","interval","number");
$answer[0] = $hc;
$answer[1] = "[0,$b]";
$answer[2] = $aroc;

// === QUESTION TEXT ===
<p>A model rocket is launched straight up from the ground. Its height in feet, `t` seconds after launch, is modeled by</p>
<p style="text-align:center">`h(t) = -16t^2 + $v0 t`</p>
<p><b>(a)</b> Find the height of the rocket at `t = $c` seconds. $answerbox[0] feet</p>
<p><b>(b)</b> Find the domain of `h` for this model. Give your answer in interval notation. $answerbox[1]</p>
<p><b>(c)</b> Find the average rate of change of the height of the rocket from `t = $p` to `t = $q` seconds. $answerbox[2] feet per second</p>
<br />

// === ANSWER ===
if ($aroc > 0) {
  $interp = 'The average rate of change is positive, so on this interval the rocket was gaining height on average.';
} else {
  $interp = 'The average rate of change is negative, so on this interval the rocket was losing height on average.';
}
$solutionguide = '<details><summary>Show worked solution</summary>
<p><b>Step 1: Evaluate the model.</b> Substitute `t = ' . $c . '` into the height model:</p>
<p style="text-align:center">`h(' . $c . ') = -16(' . $c . ')^2 + ' . $v0 . '(' . $c . ') = ' . $term1c . ' + ' . $term2c . ' = ' . $hc . '`</p>
<p>At `t = ' . $c . '` seconds the rocket is ' . $hc . ' feet above the ground.</p>
<p><b>Step 2: Find the domain.</b> The model applies only from launch until the rocket returns to the ground, so set `h(t) = 0`:</p>
<p style="text-align:center">`-16t^2 + ' . $v0 . 't = 0`</p>
<p style="text-align:center">`-16t(t - ' . $b . ') = 0`</p>
<p>This gives `t = 0` or `t = ' . $b . '`. The rocket is in the air from `t = 0` through `t = ' . $b . '`, so the domain is the closed interval from 0 to ' . $b . ', written [0, ' . $b . ']. The negative times in the algebraic solution have no meaning here.</p>
<p><b>Step 3: Compute the average rate of change.</b> First find the two heights:</p>
<p style="text-align:center">`h(' . $q . ') = ' . $hq . '` and `h(' . $p . ') = ' . $hp . '`</p>
<p>Then divide the change in height by the change in time:</p>
<p style="text-align:center">`(' . $hq . ' - ' . $hp . ')/(' . $q . ' - ' . $p . ') = ' . $dh . '/' . $dt . ' = ' . $aroc . '`</p>
<p>' . $interp . '</p>
<p><b>Answer:</b> `h(' . $c . ') = ' . $hc . '` feet; domain [0, ' . $b . ']; average rate of change `' . $aroc . '` feet per second.</p>
</details>';

// === NAME - DESCRIPTION: Best-Fit Line Concept - Predict yhat from a candidate regression line, compute the residual at one point, and interpret what the sign of that residual says about the line ===
