$rot = rand(0, 5);
$signFlip = 1;
if (rand(0, 1) == 1) {
    $signFlip = -1;
}

$weekList = array(1, 2, 3, 4, 5, 6);
$madeList = array();
for ($j = 0; $j < 6; $j++) {
    $off = ($j + $rot) % 6;
    $madeList[$j] = $intcpt + $slope * $weekList[$j] + $signFlip * $pat[$off];
}

$ptIdx = rand(1, 4);
$pickWeek = $weekList[$ptIdx];
$pickMade = $madeList[$ptIdx];
$pickPred = $intcpt + $slope * $pickWeek;
