$madeRow = $madeRow . '<td>' . $madeList[2] . '</td>';
$madeRow = $madeRow . '<td>' . $madeList[3] . '</td>';
$madeRow = $madeRow . '<td>' . $madeList[4] . '</td>';
$madeRow = $madeRow . '<td>' . $madeList[5] . '</td>';

if ($pickResid > 0) {
    $signText = 'The residual is positive, so the actual value is larger than the prediction. The point sits above the line, which means this candidate line under-predicts at `x = ' . $pickWeek . '`.';
    $signAnswer = 'positive, so the point is above the line and the line under-predicts at that x';
} else {
    $signText = 'The residual is negative, so the actual value is smaller than the prediction. The point sits below the line, which means this candidate line over-predicts at `x = ' . $pickWeek . '`.';
    $signAnswer = 'negative, so the point is below the line and the line over-predicts at that x';
}

$anstypes = "number,number,choices";
$answer[0] = $pickPred;
$answer[1] = $pickResid;

$questions[2] = array(
