// === NAME - DESCRIPTION: Matrix Inverse and Equation 3x3 - Find det A, then the inverse of a 3x3 matrix with integer entries, then solve AX = B by the inverse method X = A^-1 B ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$l1 = randfrom(array(-2,-1,1,2));
