$a11 = $sg;
$a12 = $sg*$u1;
$a13 = $sg*$u2;
$a21 = $l1;
$a22 = $l1*$u1 + 1;
$a23 = $l1*$u2 + $u3;
$a31 = $l2;
$a32 = $l2*$u1 + $l3;
$a33 = $l2*$u2 + $l3*$u3 + 1;

$c11 = $a22*$a33 - $a23*$a32;
$c12 = -($a21*$a33 - $a23*$a31);
$c13 = $a21*$a32 - $a22*$a31;
$c21 = -($a12*$a33 - $a13*$a32);
$c22 = $a11*$a33 - $a13*$a31;
$c23 = -($a11*$a32 - $a12*$a31);
$c31 = $a12*$a23 - $a13*$a22;
$c32 = -($a11*$a23 - $a13*$a21);
$c33 = $a11*$a22 - $a12*$a21;

$detA = $a11*$c11 + $a12*$c12 + $a13*$c13;

$n11 = $detA*$c11;
$n12 = $detA*$c21;
$n13 = $detA*$c31;
$n21 = $detA*$c12;
$n22 = $detA*$c22;
$n23 = $detA*$c32;
$n31 = $detA*$c13;
$n32 = $detA*$c23;
$n33 = $detA*$c33;

$x1 = randfrom(array(-4,-3,-2,-1,1,2,3,4));
$x2 = randfrom(array(-4,-3,-2,-1,1,2,3,4));
$x3 = randfrom(array(-4,-3,-2,-1,1,2,3,4));
$b1 = $a11*$x1 + $a12*$x2 + $a13*$x3;
$b2 = $a21*$x1 + $a22*$x2 + $a23*$x3;
$b3 = $a31*$x1 + $a32*$x2 + $a33*$x3;

$Amat = "[[" . $a11 . "," . $a12 . "," . $a13 . "],[" . $a21 . "," . $a22 . "," . $a23 . "],[" . $a31 . "," . $a32 . "," . $a33 . "]]";
$Bmat = "[[" . $b1 . "],[" . $b2 . "],[" . $b3 . "]]";
$Xmat = "[[" . $x1 . "],[" . $x2 . "],[" . $x3 . "]]";
$Cmat = "[[" . $c11 . "," . $c12 . "," . $c13 . "],[" . $c21 . "," . $c22 . "," . $c23 . "],[" . $c31 . "," . $c32 . "," . $c33 . "]]";
$Imat = "[[" . $n11 . "," . $n12 . "," . $n13 . "],[" . $n21 . "," . $n22 . "," . $n23 . "],[" . $n31 . "," . $n32 . "," . $n33 . "]]";

