$answer[0] = $detA;
$answer[1] = "[(" . $n11 . "," . $n12 . "," . $n13 . "),(" . $n21 . "," . $n22 . "," . $n23 . "),(" . $n31 . "," . $n32 . "," . $n33 . ")]";
$answer[2] = "[(" . $x1 . "),(" . $x2 . "),(" . $x3 . ")]";
